const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Outbound sequence</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · emails go only to the address you enter yourself, at most three, and every one has a stop link.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that sequence</h1><p class="muted">The link may be old (sequences are kept for 7 days). Start a new one below.</p><a class="btn" href="${BASE}">Open the demo</a></div>`);
const b64 = (x) => Buffer.from(String(x), 'utf8').toString('base64');
const wrap76 = (x) => x.replace(/.{1,76}/g, (m) => m + '\r\n');
const mime = ({ to, subject, text, html, id, inReplyTo }) => {
  const alt = 'alt_' + id;
  const m = ['From: "Aqib at Harborline Software (demo)" <' + ME + '>', 'To: ' + to, 'Subject: =?UTF-8?B?' + b64(subject) + '?=', 'MIME-Version: 1.0', 'X-Harborline-Demo: sequence'];
  if (inReplyTo) m.push('In-Reply-To: ' + inReplyTo, 'References: ' + inReplyTo);
  m.push(`Content-Type: multipart/alternative; boundary="${alt}"`, '', '--' + alt, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(text)), '--' + alt, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(html)), '--' + alt + '--', '');
  return b64(m.join('\r\n')).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};
const emailHtml = (bodyText, token, step) => `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1d2433;font-size:15px;line-height:1.55"><div style="white-space:pre-wrap">${esc(bodyText)}</div><hr style="border:0;border-top:1px solid #e3e8ef;margin:24px 0 12px"><p style="font-size:12px;color:#6b7485">Email ${step} of 3 from a live n8n demo you started yourself at ${BASE}. The next email arrives automatically unless you reply or <a href="${BASE}/stop?t=${token}">stop the sequence</a>. Harborline Software is a fictional company; nothing is being sold.</p></div>`;
// ---- end shared helpers ----

// Public page: start a 3-step outbound sequence to your own inbox
const SAMPLES = [
  { name: 'Sophie', company: 'Marlow & Finch Accountants', about: 'A 9-person accounting practice in Bristol that onboards about 12 new clients a month', pain: 'Chasing clients for documents by email takes hours every week' },
  { name: 'Daniel', company: 'Kim Logistics', about: 'A freight forwarder with 30 staff handling 200 shipments a week', pain: 'Booking confirmations are typed by hand from emails into the TMS' },
  { name: 'Priya', company: 'Nair Dental Group', about: 'Three dental clinics in Manchester with a shared front desk', pain: 'No-shows and reminder calls' },
];
const body = `<div class="card"><span class="st st-info">AI outbound sequence</span>
<h1>Three personalised emails, written by AI, that stop the moment the lead replies</h1>
<p class="muted">Enter a lead the way it would sit in your CRM, with <b>your own email address</b> as the lead's address. Gemini writes a 3-step sequence for that lead, n8n sends step 1 now and steps 2 and 3 after 3 and 6 minutes (days, in real life), checks the thread every minute and stops as soon as a reply arrives. Everything is logged to Google Sheets.</p>
<form method="post" action="${BASE}" id="f">
<label>Lead's first name<input name="name" required maxlength="40" placeholder="Sophie"></label>
<label>Company<input name="company" required maxlength="80" placeholder="Marlow &amp; Finch Accountants"></label>
<label>What the company does (one line)<input name="about" required maxlength="160" placeholder="A 9-person accounting practice in Bristol that onboards 12 new clients a month"></label>
<label>A pain point you know about (optional)<input name="pain" maxlength="160" placeholder="Chasing clients for documents by email takes hours every week"></label>
<label>Your email address (the sequence is sent here, and only here)<input name="email" type="email" required maxlength="120" placeholder="you@yourcompany.com"></label>
<div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<button class="btn" type="submit">Write the sequence and send step 1 →</button>
<p class="small muted" style="margin-top:12px">Takes about 10 seconds. One sequence per email address at a time, at most 3 emails, each with a stop link. Reply to any of them to watch the sequence stop.</p></form>
<div class="warnbox">Public demo. Only use an inbox that belongs to you. Harborline Software is a fictional company and nothing is being sold; the emails exist to show the automation.</div></div>
<div class="card"><h2>Or start from a sample lead (add your own email)</h2><div class="samples">
${SAMPLES.map((s, i) => `<div class="sample"><h3>${esc(s.name)} · ${esc(s.company)}</h3><p>${esc(s.about)}</p><button type="button" data-i="${i}" class="use">Use this</button></div>`).join('')}
</div></div>
<div class="card"><h2>What happens when you press the button</h2><ol class="small" style="margin:0;padding-left:20px">
<li><b>Google Gemini</b> writes three short emails for this lead: an intro with a specific hook, a follow-up with a concrete example, and a polite break-up, each with its own subject line.</li>
<li>n8n sends <b>step 1 right away</b> through the Gmail API and books steps 2 and 3 for 3 and 6 minutes later, in the same thread.</li>
<li>Every minute a schedule checks the Gmail thread. A <b>reply stops the sequence</b> and the reply is logged; a bounce stops it too; the stop link in every email also stops it.</li>
<li>Each event (sent, replied, stopped, completed) is a row in <b>Google Sheets</b>, and the owner view shows all live sequences.</li></ol></div>
<script>
var S = ${JSON.stringify(SAMPLES)};
document.querySelectorAll('button.use').forEach(function (b) { b.addEventListener('click', function () { var s = S[+b.dataset.i]; var f = document.getElementById('f'); f.name.value = s.name; f.company.value = s.company; f.about.value = s.about; f.pain.value = s.pain; f.scrollIntoView({ behavior: 'smooth', block: 'start' }); f.email.focus(); }); });
document.getElementById('f').addEventListener('submit', function () { var b = this.querySelector('button.btn'); b.textContent = 'Writing the sequence and sending step 1…'; b.style.opacity = '.75'; });
</script>`;
return [{ json: { html: page('AI outbound sequence – Harborline Software', body) } }];

