  const hdr = (m, n) => { const h = ((m.payload || {}).headers || []).find((x) => x.name.toLowerCase() === n.toLowerCase()); return h ? h.value : ''; };
  const foreign = msgs.find((m) => { const from = hdr(m, 'From').toLowerCase(); return from && !from.includes(ME); });
  const thread = 'https://mail.google.com/mail/#all/' + r.threadId;
  if (foreign) {
    const from = hdr(foreign, 'From');
    const bounce = /mailer-daemon|postmaster|delivery/i.test(from);
    r.status = bounce ? 'bounced' : 'replied'; r.replySnippet = String(foreign.snippet || '').slice(0, 200); r.replyAt = now; r.nextAt = null;
    const kind = bounce ? 'Bounced' : 'Reply detected';
    r.events.push({ at: now, kind, detail: r.replySnippet });
    out.push({ json: { token: r.token, kind: 'event', row: [time(), r.name, r.company, r.email, kind + (bounce ? '' : ' – sequence stopped'), r.replySnippet, thread, r.token] } });
    return;
  }
  if (!inp.due) return;
  const next = r.steps[r.step];
  if (!next) { r.status = 'completed'; r.nextAt = null; r.events.push({ at: now, kind: 'Completed', detail: 'All 3 emails sent, no reply' }); out.push({ json: { token: r.token, kind: 'event', row: [time(), r.name, r.company, r.email, 'Completed – no reply', '', thread, r.token] } }); return; }
  const lastHeader = msgs.length ? hdr(msgs[msgs.length - 1], 'Message-ID') : '';
  const raw = mime({ to: r.email, subject: next.subject, text: next.body + '\n\n--\nEmail ' + next.n + ' of 3 from a live n8n demo you started at ' + BASE + '. Reply to stop it, or open ' + BASE + '/stop?t=' + r.token, html: emailHtml(next.body, r.token, next.n), id: r.token + next.n, inReplyTo: lastHeader });
  r.nextAt = null; // re-armed after the send is confirmed
  out.push({ json: { token: r.token, kind: 'send', stepNo: next.n, sendBody: { raw, threadId: r.threadId }, row: [time(), r.name, r.company, r.email, 'Step ' + next.n + ' sent', next.subject, thread, r.token] } });
});
return out;

// After a follow-up is sent: mark the step, book the next one (runs once per item)
const d = $('Decide next action').item.json;
const store = $getWorkflowStaticData('global');
const r = store.seq[d.token];
const now = Date.now();
const ok = !!($json && $json.id);
let row = d.row;
if (r) {
  if (ok) {
    const s = r.steps[d.stepNo - 1]; if (s) { s.sentAt = now; s.messageId = $json.id; }
    r.step = d.stepNo; r.lastMsgId = $json.id;
    if (d.stepNo >= 3) { r.nextAt = now + 3 * 60000; r.events.push({ at: now, kind: 'Step 3 sent', detail: s ? s.subject : '' }); }
    else { r.nextAt = now + 3 * 60000; r.events.push({ at: now, kind: 'Step ' + d.stepNo + ' sent', detail: s ? s.subject : '' }); }
  } else {
    r.status = 'failed'; r.error = JSON.stringify($json).slice(0, 200); r.events.push({ at: now, kind: 'Send failed', detail: r.error });
    row = [d.row[0], d.row[1], d.row[2], d.row[3], 'Send failed', r.error, d.row[6], d.row[7]];
  }
}
return { json: { token: d.token, row } };

// ---- shared helpers (same in every page node) ----
const BASE = 'https://n8n.rixgpt.com/webhook/sequence';
const ME = 'your-inbox@gmail.com';
const STATUS = { drafting: ['Drafting', 'st-info'], active: ['Active', 'st-wait'], replied: ['Replied – stopped', 'st-ok'], stopped: ['Stopped by the lead', 'st-info'], completed: ['Completed – no reply', 'st-info'], bounced: ['Bounced', 'st-bad'], failed: ['Send failed', 'st-bad'] };
const domain = (u) => String(u || '').replace(/^https?:\/\/(www\.)?/i, '').split(/[\/?#]/)[0].toLowerCase();
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n, cur) => (n === null || n === undefined || Number.isNaN(+n) ? '–' : (cur ? cur + ' ' : '') + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const CSS = `*{box-sizing:border-box}body{margin:0;background:#f3f5f9;font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#1d2433}
