const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · Outbound sequence</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · emails go only to the address you enter yourself, at most three, and every one has a stop link.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that sequence</h1><p class="muted">The link may be old (sequences are kept for 7 days). Start a new one below.</p><a class="btn" href="${BASE}">Open the demo</a></div>`);
const b64 = (x) => Buffer.from(String(x), 'utf8').toString('base64');
const wrap76 = (x) => x.replace(/.{1,76}/g, (m) => m + '\r\n');
const mime = ({ to, subject, text, html, id, inReplyTo }) => {
  const alt = 'alt_' + id;
  const m = ['From: "Aqib at Harborline Software (demo)" <' + ME + '>', 'To: ' + to, 'Subject: =?UTF-8?B?' + b64(subject) + '?=', 'MIME-Version: 1.0', 'X-Harborline-Demo: sequence'];
  if (inReplyTo) m.push('In-Reply-To: ' + inReplyTo, 'References: ' + inReplyTo);
  m.push(`Content-Type: multipart/alternative; boundary="${alt}"`, '', '--' + alt, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(text)), '--' + alt, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(html)), '--' + alt + '--', '');
  return b64(m.join('\r\n')).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
};
const emailHtml = (bodyText, token, step) => `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;color:#1d2433;font-size:15px;line-height:1.55"><div style="white-space:pre-wrap">${esc(bodyText)}</div><hr style="border:0;border-top:1px solid #e3e8ef;margin:24px 0 12px"><p style="font-size:12px;color:#6b7485">Email ${step} of 3 from a live n8n demo you started yourself at ${BASE}. The next email arrives automatically unless you reply or <a href="${BASE}/stop?t=${token}">stop the sequence</a>. Harborline Software is a fictional company; nothing is being sold.</p></div>`;
// ---- end shared helpers ----

// Owner view: every sequence from the last 7 days
const store = $getWorkflowStaticData('global');
const seqs = Object.values(store.seq || {}).sort((a, b) => b.createdAt - a.createdAt);
const n = (f) => seqs.filter(f).length;
const sent = seqs.reduce((a, r) => a + (r.steps || []).filter((s) => s.sentAt).length, 0);
const fmt = (ms) => new Date(ms).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const rows = seqs.map((r) => { const st = STATUS[r.status] || STATUS.active; return `<tr><td>${fmt(r.createdAt)}</td><td><b>${esc(r.name)}</b> · ${esc(r.company)}<br><span class="muted small">${esc(r.email)}</span></td><td>${(r.steps || []).filter((s) => s.sentAt).length} / 3${r.nextAt && r.status === 'active' ? `<br><span class="muted small">next ${fmt(r.nextAt)}</span>` : ''}</td><td><span class="st ${st[1]}">${st[0]}</span>${r.replySnippet ? `<br><span class="muted small">“${esc(r.replySnippet.slice(0, 80))}”</span>` : ''}</td><td class="small">${esc(r.writtenBy || '')}</td><td>${r.threadId ? `<a href="https://mail.google.com/mail/#all/${esc(r.threadId)}" target="_blank">Gmail</a> · ` : ''}<a href="${BASE}/result?t=${r.token}" target="_blank">detail</a></td></tr>`; }).join('');
const body = `<h1>Outbound sequence – owner view</h1><p class="muted">Last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${seqs.length}</b>Sequences</div><div class="kpi"><b>${n((r) => r.status === 'active')}</b>Active now</div><div class="kpi"><b>${n((r) => r.status === 'replied')}</b>Replied</div><div class="kpi"><b>${n((r) => r.status === 'stopped')}</b>Stopped by lead</div><div class="kpi"><b>${n((r) => r.status === 'completed')}</b>Completed, no reply</div><div class="kpi"><b>${sent}</b>Emails sent</div></div>
<div class="card" style="overflow-x:auto"><table><tr><th>Started</th><th>Lead</th><th>Sent</th><th>Status</th><th>Copy by</th><th>Open</th></tr>${rows || '<tr><td colspan="6">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Event log: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Sequences tab)</a> · limits: 20 sequences a day, 3 per connection, one per address at a time, 3 emails each, hourly safety net closes anything still open.</p>`;
return [{ json: { html: page('Outbound sequence – owner view', body, true) } }];
